// Remove the generated JavaScript without rebuilding.
//
// The published layout is `.js` (the DSH plugin loader and `exports` address it), but the sources
// are `.ts` and the emitted twins are not committed (decision I in .agents/refactor/DECISIONS.md).
// They are regenerated by `pnpm build`, which every `pnpm test*` entry point runs first, so a tree
// with no artifacts is still a working checkout - it just cannot be loaded by Node until built.
//
// Only generated output is removed: `client/template.js`, `client/src/*.ts`, `vendor/*` and
// `scripts/*.mjs` are sources and are left alone. `--dry-run` reports what would go.
import { existsSync } from 'node:fs'
import { readdir, rm, stat } from 'node:fs/promises'
import path from 'node:path'
import process from 'node:process'
import { fileURLToPath } from 'node:url'

const root = path.resolve(fileURLToPath(new URL('..', import.meta.url)))
const dryRun = process.argv.includes('--dry-run')

/** Every generated `.js` under `src/` (recursive) plus the two root artifacts. */
async function generated(dir, out = []) {
  for (const entry of await readdir(path.join(root, dir), { withFileTypes: true }).catch(() => [])) {
    const rel = `${dir}/${entry.name}`
    if (entry.isDirectory()) await generated(rel, out)
    else if (entry.isFile() && entry.name.endsWith('.js')) out.push(rel)
  }
  return out
}

const targets = await generated('src')
for (const file of ['index.js', 'client.js']) {
  if (existsSync(path.join(root, file))) targets.push(file)
}

let bytes = 0
for (const file of targets) bytes += (await stat(path.join(root, file)).catch(() => ({ size: 0 }))).size

if (targets.length === 0) {
  console.log('[clean] nothing to remove; the tree has no generated artifacts')
  process.exit(0)
}

if (dryRun) {
  for (const file of targets) console.log(`[clean] would remove ${file}`)
  console.log(`[clean] dry run: ${targets.length} file(s), ${(bytes / 1024).toFixed(1)} KiB`)
  process.exit(0)
}

for (const file of targets) await rm(path.join(root, file), { force: true })
console.log(
  `[clean] removed ${targets.length} generated file(s), ${(bytes / 1024).toFixed(1)} KiB; run \`pnpm build\` to restore`,
)
